import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.Ddwm6YJC.js";const m=JSON.parse('{"title":"第49章 调整信","description":"","frontmatter":{},"headers":[],"relativePath":"第49章_调整信.md","filePath":"第49章_调整信.md"}'),r={name:"第49章_调整信.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第49章-调整信" tabindex="-1">第49章 调整信 <a class="header-anchor" href="#第49章-调整信" aria-label="Permalink to &quot;第49章 调整信&quot;">​</a></h1><p>冬初，南雾县的雾沉得化不开，早自习还没开始，教室只亮了半边灯，风从窗缝挤进来，带着干冷。林小满把一封叠得很整齐的信放在我桌角，说有人托她带给我。我一眼认出那是江苒的字，纸角压得很平，边上系了一颗小小的纸星星，纸星星的角被指尖压得服帖。</p><p>我把信攥在手心，纸面微凉，指尖能摸到折痕，折痕深而直，是反复对折压出来的。我没敢立刻打开，心跳慢慢变快，喉咙有点发干，手心也沁出薄汗。陈默从后门进来，看见我的样子，把书包放下，低声问我怎么了。我摇摇头，说没事，只是忽然有点不敢看，指腹在信封边角来回摩挲，把纸边都捻软了。</p><p>上午的课我听得很恍惚，黑板上的字忽远忽近，粉笔灰落在讲台上，带着干燥的气味，暖气片在墙角轻轻响，烘得指腹发干。风从窗缝挤进来，带着远处海上的咸，吹得窗帘轻轻晃动。我把信夹在书页里，书页间还夹着之前那封冷静信的回执，纸面相蹭，沙沙轻响。偶尔瞥一眼，心里像有潮水在退，又在涨，一会儿想拆，一会儿又怕看。</p><p>中午铃响，教室里椅子拖动的声响混成一片，我独自去了操场边的老槐树下，那里平时很少有人来。叶子早落尽了，枝子在灰白的天上，底下积着一层干叶，风一过就打着旋，踩上去有很轻的碎裂声。我坐下来，把书包垫在身后，把信放在膝头，深吸一口气，冷香钻进鼻腔，才慢慢展开。手指先把信封的折口一点点挑开，尽量不撕破，再把信纸抽出，两页纸被汗洇得有点贴在一起，我用手掌把它们分开，按在膝头捋平。</p><p>江苒在开头写，见字如面。她说这些日子想了许多，夜里睡不着，就把心里的潮翻来覆去地看。她说自己以前太跟着情绪走，开心就靠近，难过就躲开，让身边的人都很累。如今她慢慢调整好了，能规律作息，也能安静看完一整本书，夜里不再翻来覆去。</p><p>她写：我调整好了，能好好睡觉，好好看书，把缠在一起的线慢慢解开了 她写：也希望你别把寄托放在别人身上，包括我，一个人若总是望着别人，就容易忘记自己的路，要把脚步放回自己这边</p><p>看到这里，我眼眶有点发热，手不自觉把纸面按得更紧，指节都白了。风吹过树梢，一片干叶子落在我肩头。我把叶子拿下来，捏在指间，叶脉清晰，边缘卷脆，一使劲就断成两半。</p><p>她继续写，说这话并非要推开我，恰恰相反，是想走得更近一些。过去我们像两根缠得太紧的线，彼此都喘不过气。如今她想学着松开一点，各自站直，再好好并肩走。她问我，愿不愿意和她重新开始，把以前的别扭翻过去，重新把步子对齐。</p><p>信尾她画了一颗小星星，旁边写着，纸星星给你留着，海盐糖也还有，若是和好，我们就一起分掉。星星画得很小，角尖轻轻翘起。</p><p>我把信纸贴在胸口，闭上眼睛，纸面被掌心的汗洇得有点软，贴在皮肤上。远处传来上课铃声，悠长干净，操场上几乎没有人，只有风把旗杆上的绳子吹得一下一下响，海水的咸味从南雾县方向飘来。</p><p>我把信慢慢折回去，动作很慢，先对齐边角，再用指甲压出折痕，把信封的口折得方正，系星星的线也重新绕好，打个结。做完这些，手还是抖的。我从水杯里倒一点热水润润喉，热水烫得舌尖一紧，咽下去胃里暖了一下。树荫外蝉鸣更响，我站起来，把信揣进胸口口袋，按了按，让它贴紧心口，才往教室走。</p><p>下午我找到江苒时，她正和顾远在走廊说话，风把她的发梢吹得轻晃。看见我，她愣了一下，眼里有期待，也有不安，手里捏着半杯豆浆，杯壁沁出水珠。顾远识趣地走开，还拍了拍我的肩膀，低声说，好好说。</p><p>我说，我看了你的信。她低下头，手指绞着衣角，轻声问，你觉得如何。我说，我起初有点难受，以为你想疏远我，手里那封信被我按得都皱了。她抬起头，很认真地看着我，说，我想了很久才写下这些，我只是不想你活得那么累，也不想自己一直慌。</p><p>走廊很安静，只有风声和远处蝉鸣。阳光透过薄雾洒下来，落在她发梢，泛着柔和的光，脸颊有点热气蒸出的红。我闻到她袖口淡淡的皂香，混着纸张的气味，还有豆浆的甜香。</p><p>我说，江苒，你说得对。这些日子我也在想，我把太多心情寄托在你身上，你开心我就安心，你躲开我就慌乱。这样对你不公平，对我也不好，话说出口，手心又出汗了。</p><p>她点点头，眼圈微红，说，我们太在意对方，反而忘了照顾自己，连睡觉都忘了。</p><p>我说，可我想和你一起改。她愣住，杯子里的豆浆晃了一下。我继续说，我也调整了许多，夜里不再翻来覆去想白天的事，早上会早起跑一圈，出汗之后心里就静了，上课也更专心。我想把自己的路走稳，再陪你走。</p><p>她笑起来，眼里有泪光，齿间露出一点光，说，那我们算同时修好了各自的小船吗。我点头，说，以后潮起潮落，我们都不慌，她伸出手，说，那拉钩。我勾住她的小指晃了晃，指尖温热，心里踏实，指腹相触的那一下有点汗，却很稳。</p><p>林小满探出头来，笑着说，你们终于不别扭了，声音混着蝉鸣。陈默走过来，递给我一杯热水，说，宋阿婆托人带来的姜汤，热得很，适合今天，喝口压压汗。我握着杯子，热气扑在脸上，喝一口，辣意和暖意一起化开，喉咙都松了。</p><p>江苒从口袋掏出两颗纸星星，一颗放我手心，一颗自己留着，纸面被手温捂得有点软。她说，以前叠了许多，都放在旧的课文录音带盒里，如今想一只只送出去，第一只就给你。我把星星举到眼前，光穿过纸缝，透出暖黄的轮廓。</p><p>放学我们沿小路往海堤方向走，脚步落在石板上，有清脆的回声，蝉鸣在身后慢慢远去。江苒忽然停下，认真问我，沈聿，若以后我又钻牛角尖，你会如何。我说，我就把这封信拿出来，再读一遍，再陪你走一段。她说好，我也如此对你。</p><p>海风迎面吹来，带着咸味，吹乱她的头发，暑热被风吹散一点。我伸手帮她把发丝别到耳后，她脸颊微凉，耳朵有点红。我们没再说话，只是并肩站着，看潮水慢慢漫上来，又轻轻退下去，浪花被暑气蒸得有点白。</p><p>临别时，她把信封塞回我手里，说，这封调整信，你要收好，以后若吵架，就拿出来看看，别再把寄托全压在我身上。我点头，把信折好，放进口袋，按紧。她挥挥手，转身跑开，书包上的挂饰轻轻晃动，发尾在风里划出小弧。</p><p>晚上回到家，我把纸星星放在窗台上，窗外蝉鸣已经低了，暑气还闷在屋里。我把信重新拿出来，用手掌一遍遍抚平，把星星摆在信边，瓶里的旧星星影子晃在墙上。我拿出日记本，笔尖落在纸上，却迟迟没有写。因为我知道，和好才刚刚开始，而潮汐深处，似乎还有一封没拆开的信，正等着我。</p>',25)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
